INSERT INTO regla_sugerencia (segmento,puntaje_minimo,condicion,texto_sugerido) SELECT 'BRAZO',3,'escritorio_muy_alto','Bajar la superficie de trabajo o ajustar la altura de la silla para que los codos queden a la altura de la mesa.' WHERE NOT EXISTS (SELECT 1 FROM regla_sugerencia WHERE segmento='BRAZO' AND puntaje_minimo=3 AND condicion='escritorio_muy_alto' AND texto_sugerido='Bajar la superficie de trabajo o ajustar la altura de la silla para que los codos queden a la altura de la mesa.');
INSERT INTO regla_sugerencia (segmento,puntaje_minimo,condicion,texto_sugerido) SELECT 'CUELLO',3,'pantalla_muy_alta','Bajar la pantalla para que su borde superior quede a la altura de los ojos.' WHERE NOT EXISTS (SELECT 1 FROM regla_sugerencia WHERE segmento='CUELLO' AND puntaje_minimo=3 AND condicion='pantalla_muy_alta' AND texto_sugerido='Bajar la pantalla para que su borde superior quede a la altura de los ojos.');
INSERT INTO regla_sugerencia (segmento,puntaje_minimo,condicion,texto_sugerido) SELECT 'TRONCO',3,'pies_colgando','Instalar un reposapiés o bajar la silla para apoyar los pies completos y evitar inclinar el tronco.' WHERE NOT EXISTS (SELECT 1 FROM regla_sugerencia WHERE segmento='TRONCO' AND puntaje_minimo=3 AND condicion='pies_colgando' AND texto_sugerido='Instalar un reposapiés o bajar la silla para apoyar los pies completos y evitar inclinar el tronco.');
INSERT INTO regla_sugerencia (segmento,puntaje_minimo,condicion,texto_sugerido) SELECT 'TRONCO',3,'tiene_apoyapies','Ajustar la altura del apoyapiés y acercar el trabajo para mantener el tronco apoyado.' WHERE NOT EXISTS (SELECT 1 FROM regla_sugerencia WHERE segmento='TRONCO' AND puntaje_minimo=3 AND condicion='tiene_apoyapies' AND texto_sugerido='Ajustar la altura del apoyapiés y acercar el trabajo para mantener el tronco apoyado.');
INSERT INTO regla_sugerencia (segmento,puntaje_minimo,condicion,texto_sugerido) SELECT 'BRAZO',3,'silla_con_apoyabrazos','Ajustar los apoyabrazos a la altura de los codos para mantener los hombros relajados.' WHERE NOT EXISTS (SELECT 1 FROM regla_sugerencia WHERE segmento='BRAZO' AND puntaje_minimo=3 AND condicion='silla_con_apoyabrazos' AND texto_sugerido='Ajustar los apoyabrazos a la altura de los codos para mantener los hombros relajados.');
INSERT INTO regla_sugerencia (segmento,puntaje_minimo,condicion,texto_sugerido) SELECT 'TRONCO',3,'silla_regulable','Regular la silla para apoyar los pies y acercarse a la superficie sin inclinar el tronco.' WHERE NOT EXISTS (SELECT 1 FROM regla_sugerencia WHERE segmento='TRONCO' AND puntaje_minimo=3 AND condicion='silla_regulable' AND texto_sugerido='Regular la silla para apoyar los pies y acercarse a la superficie sin inclinar el tronco.');
INSERT INTO regla_sugerencia (segmento,puntaje_minimo,condicion,texto_sugerido) SELECT 'BRAZO',3,'SIEMPRE','Acercar las piezas a la zona de alcance cómodo, a menos de 40 cm del borde de la mesa.' WHERE NOT EXISTS (SELECT 1 FROM regla_sugerencia WHERE segmento='BRAZO' AND puntaje_minimo=3 AND condicion='SIEMPRE' AND texto_sugerido='Acercar las piezas a la zona de alcance cómodo, a menos de 40 cm del borde de la mesa.');
